shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/tokio/tests/sync_broadcast.rs
+++ b/tokio/tests/sync_broadcast.rs
@@ -523,3 +523,47 @@
     assert_empty!(rx);
     assert_empty!(rx_resub);
 }
+
+#[test]
+fn resubscribe_closed() {
+    for capacity in [1, 2, 4].iter().copied() {
+        for messages in [0, 1, 8].iter().copied() {
+            let (tx, rx) = broadcast::channel(capacity);
+            for value in 0..messages {
+                assert_ok!(tx.send(value));
+            }
+            drop(tx);
+
+            let mut rx_resub = rx.resubscribe();
+            drop(rx);
+
+            let mut recv = task::spawn(rx_resub.recv());
+            assert!(is_closed(assert_ready_err!(recv.poll())));
+        }
+    }
+}
+
+#[test]
+fn resubscribe_closed_try_recv() {
+    for capacity in [1, 2, 4].iter().copied() {
+        for messages in [0, 1, 8].iter().copied() {
+            let (tx, rx) = broadcast::channel(capacity);
+            for value in 0..messages {
+                assert_ok!(tx.send(value));
+            }
+            drop(tx);
+
+            let mut rx_resub = rx.resubscribe();
+            drop(rx);
+
+            assert_closed!(rx_resub.try_recv());
+        }
+    }
+}
PATCH
cargo test --offline --test sync_broadcast --features full resubscribe_closed > target/broadcast-regression-before.log 2>&1; result=$?; tail -n 75 target/broadcast-regression-before.log; exit "$result"

