cd /testbed && git --no-pager diff -- tokio/tests/sync_broadcast.rs && patch -p1 <<'PATCH'
--- a/tokio/src/sync/broadcast.rs
+++ b/tokio/src/sync/broadcast.rs
@@ -666,7 +666,12 @@

     tail.rx_cnt = tail.rx_cnt.checked_add(1).expect("overflow");

-    let next = tail.pos;
+    // A closed channel's tail points one past the slot marking the closure.
+    let next = if tail.closed {
+        tail.pos.wrapping_sub(1)
+    } else {
+        tail.pos
+    };

     drop(tail);

@@ -897,6 +902,8 @@
     /// **after** it has resubscribed. This will not include elements that are
     /// in the queue of the current receiver. Consider the following example.
     ///
+    /// If the channel is closed, the returned receiver will also be closed.
+    ///
     /// # Examples
     ///
     /// ```
PATCH
if [ "$?" -ne 0 ]; then exit 1; fi
cargo test --offline --test sync_broadcast --features full > target/broadcast-regression-after.log 2>&1; result=$?; tail -n 40 target/broadcast-regression-after.log; exit "$result"

